'use strict';
/* =====================================================================
   Pumpkin add-on  (load AFTER letter.js)
   ---------------------------------------------------------------------
   1. when the prize is revealed (#scratch gets "cleared") wait 5 seconds
   2. the scratch card slides up and out, the coin fades, the pumpkin slides in from the bottom
   3. TAP THE PUMPKIN: every tap knocks one piece off. The piece tumbles down and falls off the screen.
      The pumpkin has 5 pieces (its 5 ribs), so 5 taps break it completely and only the stem is left.
      Tap a rib to knock off that rib; tap a gap and the nearest rib falls.
   4. when the last piece has fallen the stem slides off to the right and the next scene (text 'Placeholder') appears.
   The pictures (5 pieces, stem, shadow) are embedded, so no image files are needed.
   letter.js / letter.css are NOT touched.
   ===================================================================== */
(() => {
  const WAIT_MS = 5000;                        // how long the prize stays visible before the swap
  const rm = matchMedia('(prefers-reduced-motion:reduce)').matches;
  const IMG_SHADOW = 'data:image/png;base64,';
  const IMG_STEM = 'data:image/png;base64,';
  const IMG_PIECES = ['data:image/png;base64,', 'data:image/png;base64,', 'data:image/png;base64,', 'data:image/png;base64,', 'data:image/png;base64,'];   // left rib ... right rib
  const G = 96, GRID = '';             // 96x96 map of the pumpkin: 0 = nothing, 1-5 = pieces, 6 = stem (used to know what was tapped)

  /* ---------- styles ---------- */
  const st = document.createElement('style');
  st.textContent = `
  .scratch.out .swrap{translate:0 -125vh;transition:translate .95s cubic-bezier(.65,0,.35,1)}
  .coin.free.gone{opacity:0;pointer-events:none;transition:opacity .4s,scale .5s}

  .pumpkin{position:fixed;inset:0;z-index:600;display:grid;place-items:center;visibility:hidden;pointer-events:none;touch-action:none;cursor:pointer;-webkit-user-select:none;user-select:none;-webkit-tap-highlight-color:transparent}
  .pumpkin.show{visibility:visible;pointer-events:auto}
  .pslide{display:flex;flex-direction:column;align-items:center;gap:18px;translate:0 115vh;transition:translate 1.05s cubic-bezier(.22,1,.36,1) .8s}
  .pumpkin.show .pslide{translate:0 0}
  .pstage{position:relative;width:min(440px,88vw,62vh);aspect-ratio:1}
  .pshadow,.pgroup,.pl{position:absolute;inset:0}
  .pshadow{background:var(--ps) center/100% 100% no-repeat}
  .pl{background:var(--pi) center/100% 100% no-repeat;pointer-events:none}
  .pl.fall{will-change:transform}
  .phint{margin:0;min-height:1.4em;font:500 15px var(--font);color:var(--ink2);opacity:0;transition:opacity .5s 1.8s}
  .pumpkin.show .phint{opacity:1}
  .pumpkin .phint.hide{opacity:0;transition-delay:0s}

  .pumpkin.exit{pointer-events:none}
  .pumpkin.exit .pslide{translate:125vw 0;transition:translate .95s cubic-bezier(.65,0,.35,1)}
  .pumpkin.gone{display:none}
  .pscene{position:fixed;inset:0;z-index:560;display:grid;place-items:center;visibility:hidden;pointer-events:none;text-align:center;padding:24px}
  .pscene.show{visibility:visible}
  .pscene h1{margin:0;font:700 clamp(34px,8vw,80px)/1.1 var(--font);color:var(--ink);opacity:0;translate:0 26px;transition:opacity .7s .55s,translate .9s cubic-bezier(.22,1,.36,1) .55s}
  .pscene.show h1{opacity:1;translate:0 0}
  @media(prefers-reduced-motion:reduce){.pslide,.phint,.scratch.out .swrap,.pumpkin.exit .pslide,.pscene h1{transition:none}}
  `;
  document.head.appendChild(st);

  /* ---------- markup ---------- */
  const sec = document.createElement('section');
  sec.className = 'pumpkin'; sec.setAttribute('aria-label', 'Pumpkin. Tap it to break it.');
  sec.innerHTML = '<div class="pslide"><div class="pstage" id="pstage"><div class="pshadow"></div><div class="pgroup" id="pgroup"></div></div>' +
                  '<p class="phint" id="phint">Tap the pumpkin to break it</p></div>';
  document.body.appendChild(sec);
  const scene = document.createElement('section');
  scene.className = 'pscene'; scene.setAttribute('aria-label', 'Next scene');
  scene.innerHTML = '<h1>Placeholder</h1>';             // <- the next scene: put your real content here later
  document.body.appendChild(scene);

  const stage = sec.querySelector('#pstage'), group = sec.querySelector('#pgroup'), hint = sec.querySelector('#phint');
  const scratchEl = document.getElementById('scratch'), coinEl = document.getElementById('coin');
  stage.style.setProperty('--ps', 'url(' + IMG_SHADOW + ')');
  [IMG_SHADOW, IMG_STEM].concat(IMG_PIECES).forEach(s => { new Image().src = s; });   // preload

  /* ---------- the pieces ---------- */
  const layer = src => { const el = document.createElement('div'); el.className = 'pl'; el.style.setProperty('--pi', 'url(' + src + ')'); return el; };
  const label = (u, v) => { const x = Math.floor(u * G), y = Math.floor(v * G); return x < 0 || y < 0 || x >= G || y >= G ? 0 : +GRID[y * G + x]; };

  const centre = {};                                     // where each piece is, in pumpkin units (0..1)
  for (let id = 1; id <= 5; id++) {
    let sx = 0, sy = 0, n = 0;
    for (let y = 0; y < G; y++) for (let x = 0; x < G; x++) if (+GRID[y * G + x] === id) { sx += x + .5; sy += y + .5; n++; }
    centre[id] = n ? [sx / n / G, sy / n / G] : [.5, .5];
  }
  const layers = {}, remaining = new Set();
  let built = false, started = false, ready = false, won = false;

  function build() {
    if (built) return; built = true;
    group.appendChild(layer(IMG_STEM));                  // the stem is underneath and never falls
    IMG_PIECES.forEach((src, i) => { const el = layer(src); layers[i + 1] = el; remaining.add(i + 1); group.appendChild(el); });
  }

  /* a piece pops off a little, tumbles and falls off the bottom of the screen */
  function drop(id) {
    const el = layers[id]; remaining.delete(id);
    stage.appendChild(el);                               // out of the group, so it can move on its own
    if (rm) { el.style.transition = 'opacity .25s'; requestAnimationFrame(() => { el.style.opacity = 0; }); setTimeout(() => el.remove(), 300); return; }
    const S = stage.getBoundingClientRect(), size = S.width, c = centre[id];
    const ax = c[0] - .5, ay = c[1] - .5, d = Math.hypot(ax, ay) || 1, k = Math.min(1, d * 3);
    el.classList.add('fall'); el.style.transformOrigin = (c[0] * 100) + '% ' + (c[1] * 100) + '%';
    let x = 0, y = 0, rot = 0;
    let vx = ax / d * size * .3 * k + (Math.random() - .5) * size * .1;
    let vy = -size * .2 + ay / d * size * .08 * k;       // a little pop upwards, then gravity takes over
    const gr = size * 3.4, w = (vx >= 0 ? 1 : -1) * (120 + Math.random() * 160);
    const yAbs = S.top + c[1] * size;
    let last = performance.now();
    (function step(now) {
      const dt = Math.min(.05, (now - last) / 1000); last = now;
      vy += gr * dt; x += vx * dt; y += vy * dt; rot += w * dt;
      el.style.transform = 'translate(' + x + 'px,' + y + 'px) rotate(' + rot + 'deg)';
      if (yAbs + y > innerHeight + size * .8) { el.remove(); return; }
      requestAnimationFrame(step);
    })(last);
  }

  /* ---------- tapping ---------- */
  const toUnit = (cx, cy) => { const r = stage.getBoundingClientRect(); return [(cx - r.left) / r.width, (cy - r.top) / r.height]; };

  sec.addEventListener('pointerdown', e => {
    if (!ready || won || !remaining.size || (e.pointerType === 'mouse' && e.button !== 0)) return;
    e.preventDefault();
    const u = toUnit(e.clientX, e.clientY), hit = label(u[0], u[1]);
    if (!hit) return;                                    // tapped empty space around the pumpkin
    let id = remaining.has(hit) ? hit : 0;               // tapped a piece that is still there -> that one falls
    if (!id) {                                           // tapped the stem or a gap -> the nearest piece falls
      let best = 1e9;
      remaining.forEach(i => { const dd = Math.hypot(centre[i][0] - u[0], centre[i][1] - u[1]); if (dd < best) { best = dd; id = i; } });
    }
    hint.classList.add('hide');
    drop(id);
    if (!rm) group.animate([{ transform: 'none' }, { transform: 'translate(' + ((Math.random() - .5) * 6) + 'px,3px) rotate(' + ((Math.random() - .5) * 1.6) + 'deg)', offset: .3 }, { transform: 'none' }], { duration: 340, easing: 'ease-out' });
    if (!remaining.size) win();
  });

  /* ---------- all broken: the stem slides off to the right, next scene appears ---------- */
  function win() {
    won = true; ready = false;
    setTimeout(() => {
      sec.classList.add('exit');
      setTimeout(() => { sec.classList.add('gone'); }, rm ? 0 : 1100);
      setTimeout(() => { scene.classList.add('show'); }, rm ? 0 : 500);
    }, rm ? 0 : 1300);                                   // a moment to see the last piece fall and the stem stand alone
  }

  /* ---------- the hand-over: prize shown -> wait -> scratch card out, pumpkin in ---------- */
  function start() {
    if (sec.classList.contains('show')) return;
    scratchEl.classList.add('out');
    coinEl.classList.add('gone');
    build();
    sec.classList.add('show');
    setTimeout(() => { ready = true; }, rm ? 0 : 1900);   // tapping works once the pumpkin has landed
  }
  function arm() {
    if (started || !scratchEl.classList.contains('cleared')) return;
    started = true;
    setTimeout(start, rm ? 0 : WAIT_MS);
  }
  new MutationObserver(arm).observe(scratchEl, { attributes: true, attributeFilter: ['class'] });
  setInterval(arm, 300);                                 // safety net in case the class change is ever missed
  window.startPumpkin = start;                           // for testing: type startPumpkin() in the browser console
})();
